section.programlisting:
define Counter(var value: int) { procedure increment(mutable this) value := value + 1
function get(this) returns int value }
var c Counter(0) c.increment() c.increment() print "der Zähler steht bei `c.get()`"

define Point(x: int, y: int)
{
    function distance_squared(this) returns int
        this.x * this.x + this.y * this.y
}

let p Point(3, 4)
print "der Abstand im Quadrat ist `p.distance_squared()`"

define Option union(Some: int, None)

let present Option.Some(42)
let absent  Option.None

; shapes.scaly define Box(width: int, height: int) { function area(this) returns int width * height }
; myprog.scaly module shapes use myprog.shapes.Box ; oder: use myprog.shapes.*
let b Box(3, 4) if b.area() = 12 print "die Fläche ist 12"
